const c = $json;

const d = new Date(c.slot_inicio);
const fechaRaw = d.toLocaleDateString('es-CO', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'America/Bogota' });
const fecha = fechaRaw.replace(',', '');

const horaRaw = d.toLocaleTimeString('es-CO', { hour: 'numeric', minute: '2-digit', hour12: true, timeZone: 'America/Bogota' });
const hora = horaRaw.replace(/\s+/g, ' ').replace(/\bp\.\s?m\.?/i, 'p.m.').replace(/\ba\.\s?m\.?/i, 'a.m.');

const nombre = (c.cliente_nombre || '').trim();
const servicio = c.servicio_nombre;
const terapeuta = c.terapeuta_nombre;
const sede = c.sede_nombre;

const saludo = nombre ? `Hola ${nombre}` : 'Hola';
const nombreOpener = nombre ? `${nombre}, ` : '';

const variantes = [
  `${saludo}, te escribo para recordarte que mañana ${fecha} a las ${hora} tienes tu sesión de ${servicio} con ${terapeuta} en ${sede}. Si necesitas mover algo, me cuentas.`,
  `${saludo}, mañana ${fecha} te esperamos a las ${hora} para tu ${servicio} con ${terapeuta} en ${sede}. Cualquier cambio, aquí estoy.`,
  `${nombreOpener}paso a recordarte tu cita de mañana ${fecha} a las ${hora} — ${servicio} con ${terapeuta}, en ${sede}. Si surge algo, me avisas.`,
  `${saludo}, mañana ${fecha} a las ${hora} tienes ${servicio} con ${terapeuta} en ${sede}. Confírmame si todo sigue en pie, o me dices si necesitas reagendar.`,
  `${saludo}, recuerda que mañana ${fecha} a las ${hora} es tu ${servicio} con ${terapeuta} en ${sede}. Quedo atenta a cualquier cambio.`
];

const text = variantes[Math.floor(Math.random() * variantes.length)];

return [{
  json: {
    cliente_whatsapp: c.whatsapp_id,
    cliente_id: c.cliente_id,
    cita_id: c.cita_id,
    text,
  }
}];

